begin;
create table if not exists public.mme_inventory_products(product_id uuid primary key default gen_random_uuid(),sku text not null unique,product_name text not null,category text,brand text,condition text not null default 'new' check(condition in ('new','open_box','used','refurbished','parts')),unit_cost numeric(14,2) not null default 0 check(unit_cost>=0),retail_price numeric(14,2) not null default 0 check(retail_price>=0),reorder_point numeric(14,3) not null default 0 check(reorder_point>=0),is_serialized boolean not null default false,is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_inventory_locations(location_id uuid primary key default gen_random_uuid(),location_code text not null unique,location_name text not null,location_type text not null default 'store' check(location_type in ('store','warehouse','stockroom','repair','transit')),address text,is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_balances(balance_id uuid primary key default gen_random_uuid(),product_id uuid not null references public.mme_inventory_products(product_id),location_id uuid not null references public.mme_inventory_locations(location_id),quantity numeric(14,3) not null default 0,updated_at timestamptz not null default now(),unique(product_id,location_id),check(quantity>=0));
create table if not exists public.mme_inventory_movements(movement_id uuid primary key default gen_random_uuid(),product_id uuid not null references public.mme_inventory_products(product_id),location_id uuid not null references public.mme_inventory_locations(location_id),movement_type text not null check(movement_type in ('receipt','sale','return','adjustment','transfer_in','transfer_out','write_off')),quantity_delta numeric(14,3) not null check(quantity_delta<>0),unit_cost numeric(14,2) not null default 0 check(unit_cost>=0),reference_type text,reference_id text,notes text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_serial_assets(asset_id uuid primary key default gen_random_uuid(),product_id uuid not null references public.mme_inventory_products(product_id),location_id uuid references public.mme_inventory_locations(location_id),serial_number text,imei text,condition text not null default 'new' check(condition in ('new','open_box','used','refurbished','parts')),status text not null default 'in_stock' check(status in ('in_stock','sold','returned','repair','written_off','in_transit')),unit_cost numeric(14,2) not null default 0 check(unit_cost>=0),received_at timestamptz not null default now(),sold_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(serial_number is not null or imei is not null));
create unique index if not exists mme_inventory_serial_unique on public.mme_inventory_serial_assets(lower(serial_number)) where serial_number is not null;
create unique index if not exists mme_inventory_imei_unique on public.mme_inventory_serial_assets(imei) where imei is not null;
create table if not exists public.mme_inventory_receipts(receipt_id uuid primary key default gen_random_uuid(),receipt_reference text not null unique,vendor_name text not null,location_id uuid not null references public.mme_inventory_locations(location_id),received_date date not null,invoice_reference text,total_cost numeric(14,2) not null default 0 check(total_cost>=0),status text not null default 'received' check(status in ('received','void')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_transfers(transfer_id uuid primary key default gen_random_uuid(),transfer_reference text not null unique,source_location_id uuid not null references public.mme_inventory_locations(location_id),destination_location_id uuid not null references public.mme_inventory_locations(location_id),status text not null default 'completed' check(status in ('completed','void')),notes text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(source_location_id<>destination_location_id));
create table if not exists public.mme_inventory_counts(count_id uuid primary key default gen_random_uuid(),location_id uuid not null references public.mme_inventory_locations(location_id),product_id uuid not null references public.mme_inventory_products(product_id),counted_quantity numeric(14,3) not null check(counted_quantity>=0),system_quantity numeric(14,3) not null check(system_quantity>=0),variance numeric(14,3) generated always as (counted_quantity-system_quantity) stored,counted_by_auth_user_id uuid not null,notes text,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_audit(audit_id uuid primary key default gen_random_uuid(),actor_auth_user_id uuid not null,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',request_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_inventory_movement_product_date_idx on public.mme_inventory_movements(product_id,created_at desc);
create index if not exists mme_inventory_balance_location_idx on public.mme_inventory_balances(location_id,product_id);
create index if not exists mme_inventory_serial_location_status_idx on public.mme_inventory_serial_assets(location_id,status);
create index if not exists mme_inventory_counts_location_date_idx on public.mme_inventory_counts(location_id,created_at desc);
create or replace function public.mme_inventory_apply_movement(p_product_id uuid,p_location_id uuid,p_delta numeric,p_movement_type text,p_unit_cost numeric,p_reference_type text,p_reference_id text,p_notes text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid;v_current numeric; begin if p_delta=0 or p_movement_type not in ('receipt','sale','return','adjustment','transfer_in','transfer_out','write_off') then raise exception 'invalid_inventory_movement'; end if; perform 1 from public.mme_inventory_products where product_id=p_product_id and is_active for update; if not found then raise exception 'active_product_not_found'; end if; perform 1 from public.mme_inventory_locations where location_id=p_location_id and is_active for update; if not found then raise exception 'active_location_not_found'; end if; insert into public.mme_inventory_balances(product_id,location_id,quantity) values(p_product_id,p_location_id,0) on conflict(product_id,location_id) do nothing; select quantity into v_current from public.mme_inventory_balances where product_id=p_product_id and location_id=p_location_id for update; if v_current+p_delta<0 then raise exception 'insufficient_inventory'; end if; update public.mme_inventory_balances set quantity=v_current+p_delta,updated_at=now() where product_id=p_product_id and location_id=p_location_id; insert into public.mme_inventory_movements(product_id,location_id,movement_type,quantity_delta,unit_cost,reference_type,reference_id,notes,actor_auth_user_id) values(p_product_id,p_location_id,p_movement_type,p_delta,coalesce(p_unit_cost,0),p_reference_type,p_reference_id,p_notes,p_actor) returning movement_id into v_id; return v_id; end $$;
create or replace function public.mme_inventory_transfer(p_product_id uuid,p_source uuid,p_destination uuid,p_quantity numeric,p_reference text,p_notes text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_balance numeric;v_transfer uuid; begin if p_quantity<=0 or p_source=p_destination then raise exception 'invalid_transfer'; end if; perform 1 from public.mme_inventory_products where product_id=p_product_id and is_active for update; if not found then raise exception 'active_product_not_found'; end if; perform 1 from public.mme_inventory_locations where location_id in (p_source,p_destination) and is_active order by location_id for update; if (select count(*) from public.mme_inventory_locations where location_id in(p_source,p_destination) and is_active)<>2 then raise exception 'active_location_not_found'; end if; insert into public.mme_inventory_balances(product_id,location_id,quantity) values(p_product_id,p_source,0) on conflict(product_id,location_id) do nothing; insert into public.mme_inventory_balances(product_id,location_id,quantity) values(p_product_id,p_destination,0) on conflict(product_id,location_id) do nothing; perform 1 from public.mme_inventory_balances where product_id=p_product_id and location_id in(p_source,p_destination) order by location_id for update; select quantity into v_balance from public.mme_inventory_balances where product_id=p_product_id and location_id=p_source; if v_balance<p_quantity then raise exception 'insufficient_inventory'; end if; update public.mme_inventory_balances set quantity=quantity-p_quantity,updated_at=now() where product_id=p_product_id and location_id=p_source; update public.mme_inventory_balances set quantity=quantity+p_quantity,updated_at=now() where product_id=p_product_id and location_id=p_destination; insert into public.mme_inventory_transfers(transfer_reference,source_location_id,destination_location_id,notes,created_by_auth_user_id) values(p_reference,p_source,p_destination,p_notes,p_actor) returning transfer_id into v_transfer; insert into public.mme_inventory_movements(product_id,location_id,movement_type,quantity_delta,reference_type,reference_id,notes,actor_auth_user_id) values(p_product_id,p_source,'transfer_out',-p_quantity,'transfer',v_transfer::text,p_notes,p_actor),(p_product_id,p_destination,'transfer_in',p_quantity,'transfer',v_transfer::text,p_notes,p_actor); return v_transfer; end $$;
alter table public.mme_inventory_products enable row level security;alter table public.mme_inventory_locations enable row level security;alter table public.mme_inventory_balances enable row level security;alter table public.mme_inventory_movements enable row level security;alter table public.mme_inventory_serial_assets enable row level security;alter table public.mme_inventory_receipts enable row level security;alter table public.mme_inventory_transfers enable row level security;alter table public.mme_inventory_counts enable row level security;alter table public.mme_inventory_audit enable row level security;
do $$ declare t text;begin foreach t in array array['mme_inventory_products','mme_inventory_locations','mme_inventory_balances','mme_inventory_movements','mme_inventory_serial_assets','mme_inventory_receipts','mme_inventory_transfers','mme_inventory_counts','mme_inventory_audit'] loop execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
revoke all on function public.mme_inventory_apply_movement(uuid,uuid,numeric,text,numeric,text,text,text,uuid) from public,anon,authenticated;revoke all on function public.mme_inventory_transfer(uuid,uuid,uuid,numeric,text,text,uuid) from public,anon,authenticated;grant execute on function public.mme_inventory_apply_movement(uuid,uuid,numeric,text,numeric,text,text,text,uuid) to service_role;grant execute on function public.mme_inventory_transfer(uuid,uuid,uuid,numeric,text,text,uuid) to service_role;
commit;